\label{main theorem}
Let $G$ be a simply connected, $2$-step nilpotent Lie group equipped with a left-invariant sub-Riemannian metric $d$. Denote by $d_\infty$ the canonical asymptotic metric on $G$. Then, there exists $C > 0$ such that
\begin{equation} \label{main equation}
\lvert d_\infty(p,q)^2 - d(p,q)^2 \rvert \leq C, \quad \text{for every } p,q \in G.
\end{equation}
In particular
\begin{equation} \label{first consequence}
 \lvert d_\infty(p,q) - d(p,q) \rvert = O\left(\frac{1}{d(p,q)}\right) \to 0, \quad \text{as $d(p,q) \to \infty$.}
\end{equation}

\label{equivalence quasi_isometries intro}
Let $G$ be a simply connected, $2$-step nilpotent Lie group equipped with sub-Riemannian metrics $d$ and $d'$. Then, the metrics $d$ and $d'$ are asymptotic if and only if there exists $C > 0$ such that
\begin{equation*}
\lvert d'(p,q) - d(p,q) \rvert \leq C, \quad \text{for every } p,q \in G.
\end{equation*}

Let $G$ be a nilpotent simply connected Lie group with associated Lie algebra $\mathfrak{g}$. Equip $G$ with a sub-Riemannian structure $(\Delta,\rho)$ and denote by $d$ the corresponding sub-Riemannian metric.
 We define 
	\begin{equation} \label{def V}
		V \coloneqq V_{(\Delta,\rho)} \coloneqq \Set{v \in \Delta_e | \text{$\rho(v,w)=0$ for every $w \in \Delta_e \cap [\mathfrak{g},\mathfrak{g}]$}},
	\end{equation}
	\begin{equation} \label{def delta infty}
		\Delta_\infty \coloneqq \bigcup_{p \in G} \mathrm{d} L_p(V) \subseteq \Delta,
	\end{equation}
 and, for each $p,q\in G$, we define 
	\begin{equation} \label{asymptotic metric}
		d_\infty(p,q) \coloneqq \inf \Set{\ell(\gamma) | \text{$\gamma \colon [0,1] \to G$ is a $\Delta_\infty$-horizontal curve, $p,q \in \gamma([0,1])$}} .
	\end{equation}
We refer to $d_\infty$ as the \emph{canonical asymptotic metric} of the sub-Riemannian Lie group $(G,d)$.

\label{prop_asymptotic}
 Let $G$ be a nilpotent simply connected Lie group, equipped with a sub-Riemannian structure $(\Delta,\rho)$. Denote by $d$ the sub-Riemannian metric and by $d_\infty$ its canonical asymptotic metric. Then, the function $d_\infty$ is the left-invariant sub-Riemannian metric on $G$ associated with the sub-Riemannian structure $(\Delta_\infty,\rho|_{\Delta_\infty})$, the metric
 $d_\infty$ is asymptotic to $d$, and
 \begin{equation} \label{obvious bound}
 d(p,q) \le d_\infty(p,q), \quad \text{for every $p,q \in G$.}
 \end{equation}

\label{lemma integral}
	Let $G$ be as in \eqref{def G}, and let $\gamma_u \colon [0,1] \to G$ be an absolutely continuous curve such that \eqref{system} holds. Then
	\begin{equation} \label{formula integral}
		\gamma_u(1) = \int^1_0 u(t) \, \mathrm{d} t + \frac{1}{2} \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s, u(t) \right] \, \mathrm{d} t. 
	\end{equation}

\label{lemma_wedge}
Fix $G$ as in \eqref{def G}.
	Let $u,v \in L^1([0,1],\mathfrak{g})$. Assume that 
	\begin{equation*} 
			\int^1_0 v(t) \, \mathrm{d} t = 0 \quad \text{and} \quad \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , v(t)\right] \mathrm{d} t = 0.
	\end{equation*}
	Then $\gamma_{u+v}(1)=\gamma_u(1) + \gamma_v(1)$.

Integrating by parts, we get
\begin{equation} \label{parts}
 \int^1_0 \left[\int^t_0 v(s) \, \mathrm{d} s , u(t)\right] \mathrm{d} t = - \int^1_0 \left[ v(t), \int^t_0 u(s) \mathrm{d} s \right] \mathrm{d} t = \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , v(t)\right] \mathrm{d} t,
\end{equation}
where we used the fact that $\int^1_0 v(t) \, \mathrm{d} t = 0$. We then compute
\begin{eqnarray*}
 \gamma_{u+v}(1) &\stackrel{\eqref{formula integral}}{=}& \int^1_0 u(t) +v(t) \, \mathrm{d} t + \frac{1}{2} \int^1_0 \left[\int^t_0 u(s) + v(s) \, \mathrm{d} s, u(t)+v(t) \right] \, \mathrm{d} t. \\
 &\stackrel{\eqref{formula integral},\eqref{parts}}{=}& \gamma_u(1) + \gamma_v(1) + \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , v(t)\right] \mathrm{d} t \\
 &=& \gamma_u(1) + \gamma_v(1),
\end{eqnarray*}
 where in the last equality we used the hypothesis $\int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , v(t)\right] \mathrm{d} t = 0$.

\label{energy}
Let $(\Delta,\rho)$ be a sub-Riemannian structure on a Lie group $G$. Let $\gamma \colon [0,1] \to G$ be a $\Delta$-horizontal curve. We say that $\gamma$ is \emph{energy-minimizing} if 
	\begin{equation} \label{def_minimizing}
	\int^1_0 \rho(\dot{\gamma}(t),\dot{\gamma}(t)) \, \mathrm{d} t= d(\gamma(0),\gamma(1))^2.
 \end{equation}

We point out that the complexification $\mathfrak{g}_\mathbb C$ of a real Lie algebra $\mathfrak{g}$ is also a real Lie algebra. Moreover, $\mathfrak{g}$ is a Lie subalgebra of $\mathfrak{g}_\mathbb C$. If $\mathfrak{g}$ is 2-step nilpotent, then also $\mathfrak{g}_\mathbb C$ is 2-step nilpotent. If a Lie group $G$ is as in \eqref{def G}, then we define 
 \begin{equation} \label{def Gc}
 G_\mathbb C:= (\mathfrak{g}_\mathbb C,*), \quad \text{where} \quad x*y \coloneqq x+y+\tfrac{1}{2}[x,y], \qquad \text{ for all } x,y \in \mathfrak{g}_\mathbb C.
\end{equation}
Clearly, $G$ is a Lie subgroup of $G_\mathbb C$.

\label{lemma lemma}
 Let $\mathfrak{g}$ be a 2-step nilpotent Lie algebra, and fix an inner product $\rho$ on a subspace $\Delta \subseteq \mathfrak{g}$. Let $G_\mathbb C$ be as in \eqref{def Gc}, and consider $v \in L^2([0,1],\Delta_\mathbb C)$ such that
 \begin{equation} \label{def_xi_lemma}
 v(t) = \sum_{n \in E} c_nf_n(t), 
 \end{equation}
 for some finite subset of non-zero integers $E$, and some $\{c_n\}_{n\in E} \subseteq \Delta_\mathbb C$. Then
 \begin{equation} \label{complex_endpoint_1}
 \gamma_v(1) = \sum_{n \in E} \frac{1}{4 \pi i n} [c_n,c_{-n}] \quad \text{and} \quad \int^1_0 \rho(v(t),v(t)) \, \mathrm{d} t
 = \sum_{n \in E} \rho(c_n,c_n).
\end{equation}

First, for every $t \in [0,1]$, we compute
 \begin{eqnarray} \label{int_xi_t}
 \int^t_0 v(s) \, \mathrm{d} s &\stackrel{\eqref{def_xi_lemma}}{=}& \int^t_0 \sum_{n \in E} c_nf_n(t) \, \mathrm{d} t = \sum_{n \in E} \frac{c_n}{2 \pi i n}(f_n(t)-1).
 \end{eqnarray}
 where in the second equality we used that $0 \notin E$. In particular, we obtain $\int^1_0 v(t) \, \mathrm{d} t = 0$. Thus, we compute
 \begin{eqnarray*}
 \gamma_v(1) &\stackrel{\eqref{formula integral}}{=}& \int^1_0 v(t) \, \mathrm{d} t + 
 \frac{1}{2} \int^1_0 \left[\int^t_0 v(s) \, \mathrm{d} s, v(t) \right] \, \mathrm{d} t \\ &\stackrel{\eqref{def_xi_lemma}\eqref{int_xi_t}}{=}& \frac{1}{2} \int^1_0 \left[ \sum_{n \in E} \frac{c_n}{2 \pi i n}(f_n(t)-1), \sum_{m \in E} c_mf_m(t)\right] \, \mathrm{d} t \\
 &=& \sum_{m,n \in E} \frac{1}{4\pi i n} [c_n,c_m] \int^1_0 (f_n(t)-f_0(t))f_m(t) \, \mathrm{d} t \\
 &\stackrel{\eqref{def_f_prop}}{=}& \sum_{n,m \in E} \frac{1}{4\pi in} [c_n,c_{m}]\delta_{n,-m} = \sum_{n \in E} \frac{1}{4\pi in} [c_n,c_{-n}]. 
 \end{eqnarray*} 
 We then verified the first identity in \eqref{complex_endpoint}. For the second one, we compute 
 \begin{eqnarray*}
 \int^1_0 \rho(v(t),v(t)) \, \mathrm{d} t &\stackrel{\eqref{def_xi_lemma}}{=}& \int^1_0 \rho\left(\sum_{n \in E} c_nf_n(t),\sum_{m \in E} c_mf_m(t)\right) \, \mathrm{d} t \\
 &=& \sum_{m,n \in E} \rho(c_n,c_m)\int^1_0 f_n(t)\overline{f_m}(t) \, \mathrm{d} t \\
 &\stackrel{\eqref{def_f_prop}}{=}& \sum_{m,n \in E} \rho(c_n,c_m) \delta_{n,m} \, \mathrm{d} t = \sum_{n \in E} \rho(c_n,c_n),
 \end{eqnarray*}
 where we used that $\rho$ is Hermitian and that $\overline{f_m}(t)=f_{-m}(t)$, for every $m \in \mathbb Z$ and $t \in [0,1]$.

\label{corollary_ortogonal}
 Let $G$ be as in \eqref{def G}, and fix an inner product $\rho$ on a subspace $\Delta \subseteq \mathfrak{g}$. Consider $v \in L^2([0,1],\Delta)$ such that
 \begin{equation*} 
 v(t) = \sum_{n \in E} \operatorname{Re}(c_nf_n(t)), 
 \end{equation*}
 for some finite subset of positive integers $E$, and some $\{c_n\}_{n\in E} \subseteq (\Delta_e)_\mathbb C$. Then
\begin{equation} \label{complex_endpoint}
 \gamma_v(1) = \sum_{n \in E} \frac{1}{4 \pi n} [\operatorname{Im}(c_n),\operatorname{Re}(c_n)] \quad \text{and} \quad \int^1_0 \rho(v(t),v(t)) \, \mathrm{d} t = \frac{1}{2} \sum_{n \in E} \rho(c_n,c_n).
\end{equation}

In the assumptions of the statement, we get
 \begin{equation} \label{vre}
 v(t)=\sum_{n \in E} \operatorname{Re}(c_nf_n(t))=\sum_{n \in E} \frac{c_n}{2}f_n(t) + \sum_{n \in E} \frac{\overline{c_n}}{2}f_{-n}(t).
 \end{equation}
 Therefore, applying \cref{lemma lemma}, we compute
 \begin{eqnarray*}
 \gamma_v(1) &\stackrel{\eqref{complex_endpoint_1}\eqref{vre}}{=}& \sum_{n \in E} \frac{1}{4 \pi i n}\left[\frac{c_n}{2}, \frac{\overline{c_n}}{2}\right] - \sum_{n \in E} \frac{1}{4 \pi i n}\left[\frac{\overline{c_n}}{2},\frac{c_n}{2} \right]\\
 &=& \sum_{n \in E} \frac{1}{8 \pi i n}\left[c_n,\overline{c_n} \right] \\
 &=&\sum_{n \in E} \frac{1}{8 \pi i n} \left(\left[\operatorname{Re}(c_n),-i \operatorname{Im}(c_n)\right]+ \left[i \operatorname{Im}(c_n), \operatorname{Re}(c_n)\right]\right) \\
 &=& \sum_{n \in E} \frac{1}{4 \pi n} \left[\operatorname{Im}(c_n), \operatorname{Re}(c_n)\right].
 \end{eqnarray*}
 We then verified the first identity in \eqref{complex_endpoint}. For the second one, we also apply \cref{lemma lemma} to compute
 \begin{eqnarray*}
 \int^1_0 \rho_e(v(t),v(t)) \, \mathrm{d} t &\stackrel{\eqref{complex_endpoint_1}\eqref{vre}}{=}& \sum_{n \in E } \frac{1}{4} \rho(c_n,c_n) + \sum_{n \in E } \frac{1}{4} \rho(\overline{c_n},\overline{c_n}) = \frac{1}{2}\sum_{n \in E } \rho(c_n,c_n),
 \end{eqnarray*}
 where we used that $\rho$ is Hermitian to obtain $\rho(\overline{c_n},\overline{c_n})=\rho(c_n,c_n)$.

We set $m \coloneqq \dim([V,V])$, and $K > 0$ to be the constant given in \cref{equivalence_norms} for the norm $\lvert \cdot \rvert$ on $[\mathfrak{g},\mathfrak{g}]$ and the restriction to $V$ of the inner product $\rho_e$. Fix $\zeta \in [\mathfrak{g},\mathfrak{g}]$. Thanks to \cref{equivalence_norms}, there exist $x_1,\dots,x_{m} \in V$, $y_1,\dots,y_{m} \in V$, and $\alpha_1,\dots,\alpha_{m} \ge 0$, satisfying $\rho_e(x_k,x_k)=\rho_e(y_k,y_k)=1$ and $\rho_e(x_k,y_k)=0$ for every $1 \le k \le m$, such that
\begin{equation} \label{zeta_brakets}
 \zeta = \sum_{k=1}^{m} \alpha_k[x_k,y_k] \quad \text{and} \quad \sum_{k=1}^{m} \alpha_k \le K \lvert \zeta \rvert.
\end{equation}

	Next, we set $E_k \coloneqq [(m+2)(k-1)+1, (m+2)k] \cap \mathbb Z$, for every $1 \le k \le m$,	and we observe that $\{E_k\}_{k=1}^{m}$ is a family of pairwise disjoint subsets of positive integers. We also set $N \coloneqq m^2 + 2m$, so that we get
	\begin{equation} \label{bound_N}
		n \le N, \quad \text{for every $1 \le k \le m$ and $n \in E_k$.}
	\end{equation}
We fix $u \in L^2([0,1],\Delta_e)$. For every $n \in \mathbb Z$ and $\xi \in V_\mathbb C$, we define
	\begin{equation*}
		P^n_\xi \coloneqq \int^1_0 f_n(t) \rho_e(\xi,u(t)) \, \mathrm{d} t \in \mathbb{C}, \quad Q^n_\xi \coloneqq \int^1_0 f_n(t) \left[ \int^t_0 u(s) \, \mathrm{d} s , \xi \right] \mathrm{d} t \in [V,V]_\mathbb{C},
	\end{equation*}
	with $f_n$ defined as in \eqref{def_f}. For every $1 \le k \le m$, we consider the tuple $\{z_{n,k}\}_{n \in E_k} \subseteq \mathbb{C}$ to be a solution of the following system of equations:
	\begin{equation} \label{system_c}
		\begin{cases}
			\sum_{n \in E_k} z_{n,k}P^n_{y_k + ix_k} = 0, \\
			\sum_{n \in E_k} z_{n,k}Q^n_{y_k + ix_k} = 0, \\
			\sum_{n \in E_k} \tfrac{1}{4 \pi n} \lvert z_{n,k} \rvert^2 = \alpha_k.
		\end{cases}
	\end{equation}
	We claim that such a solution exists. Indeed, a non-trivial solution to the linear part of the system exists since there are $m + 1$ equations and $\lvert E_k \rvert = m + 2$ variables. Such a solution can be normalized so that the last equation is also satisfied. We recall that $\alpha_k \ge 0$.

 Next, for every $1 \le k \le m$, we define $v_k \colon [0,1] \to V$ such that
 \begin{equation} \label{def_vk}
 v_k(t) \coloneqq \sum_{n \in E_k} \operatorname{Re}\left(z_{n,k}(y_k+ix_k)f_n(t)\right), \quad \text{for every $t \in [0,1]$.} 
 \end{equation}
 In what follows, we show that $v \coloneqq \sum_{k=1}^{m} v_k \in L^2([0,1],V)$ satisfies the conditions of the statement.

For proving \emph{(i)}, we first claim that $\gamma_v(1) = \zeta$. Indeed, we observe that the sets $E_k$ are pairwise disjoint, and we compute:
 \begin{eqnarray}
 \gamma_v(1)&\stackrel{\eqref{complex_endpoint}}{=}& \sum_{k=1}^m \sum_{n \in E_k} \frac{1}{4 \pi n} [\operatorname{Im}(z_{n,k}(y_k+ix_k)),\operatorname{Re}(z_{n,k}(y_k+ix_k))] \notag \\
 &=& \sum_{k=1}^m \sum_{n \in E_k} \frac{1}{4 \pi n} \lvert z_{n,k}\rvert^2 [x_k,y_k] \stackrel{\eqref{system_c}}{=} \sum_{k=1}^m \alpha_k[x_k,y_k] \stackrel{\eqref{zeta_brakets}}{=} \zeta. \label{end_v}
 \end{eqnarray}





Next, we claim that $\gamma_{u+v}(1)=\gamma_u(1)+\gamma_v(1)$. Indeed, we observe that $\int^1_0 v(t) \, \mathrm{d} t = 0$ and we compute
\begin{eqnarray*}
 \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , v(t)\right] \mathrm{d} t &=& \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , \sum_{k=1}^mv_k(t)\right] \mathrm{d} t \\
 &=& \sum_{k=1}^m \sum_{n \in E_k} \int^1_0 \left[\int^t_0 u(s) \, \mathrm{d} s , \operatorname{Re}\left(z_{n,k}(y_k+ix_k)f_n(t)\right)\right] \mathrm{d} t \\
 &=& \sum_{k=1}^m \operatorname{Re}\left(\sum_{n \in E_k}z_{n,k}\int^1_0 f_n(t) \left[\int^t_0 u(s) \, \mathrm{d} s , y_k+ix_k \right] \mathrm{d} t\right) \\
 &=& \sum_{k=1}^m \operatorname{Re}\left(\sum_{n \in E_k} z_{n,k} Q^n_{y_k + ix_k}\right) \stackrel{\eqref{system_c}}{=} 0.
\end{eqnarray*}
Therefore, the hypothesis of \cref{lemma_wedge} are satisfied and we get that 
$$\gamma_{u+v}(1)=\gamma_u(1)+\gamma_v(1)\stackrel{\eqref{end_v}}{=}\gamma_u(1)+\zeta.$$ In particular, \emph{(i)} is verified.

Next, we check \emph{(ii)}, i.e., $\int^1_0 \rho_e(v(t),u(t))\, \mathrm{d} t =0$. We compute
\begin{eqnarray*}
 \int^1_0 \rho_e(v(t),u(t))\, \mathrm{d} t &=& \sum_{k=1}^m \left(\int^1_0 \rho_e(v_k(t),u(t))\, \mathrm{d} t \right) \\ &=& \sum_{k=1}^m \sum_{n \in E_k} \left(\int^1_0 \rho_e(\operatorname{Re}\left(z_{n,k}(y_k+ix_k)f_n(t)\right),u(t))\, \mathrm{d} t \right) \\ &=& \sum_{k=1}^m \operatorname{Re}\left(\sum_{n \in E_k} z_{n,k} \int^1_0 f_n(t)\rho_e(y_k+ix_k,u(t))\, \mathrm{d} t \right) \\ &=& \sum_{k=1}^m \operatorname{Re}\left(\sum_{n \in E_k} z_{n,k} P^n_{w_k + iv_k}\right) \stackrel{\eqref{system_c}}{=} 0,
\end{eqnarray*}
where in the third equality we used the fact that $u(t) \in V$ in order to move the operator $\operatorname{Re}$ outside the Hermitian product. Thus, \emph{(ii)} is verified.

Finally, to prove \emph{(iii)}, we estimate
\begin{eqnarray*}
 \int^1_0 \rho_e(v(t),v(t))\, \mathrm{d} t &\stackrel{\eqref{complex_endpoint}}{=}& \frac{1}{2} \sum_{k=1}^m \sum_{n \in E_k} \lvert z_{n,k} \rvert^2 \rho_e(y_k+ix_k,y_k+ix_k) \\
 &=& \sum_{k=1}^m \sum_{n \in E_k} \lvert z_{n,k} \rvert^2 \le 4 \pi N \sum_{k=1}^m \sum_{n \in E_k} \frac{1}{4\pi n}\lvert z_{n,k} \rvert^2 \\
 &\stackrel{\eqref{system_c}}{=}& 4 \pi N \sum_{k=1}^m \alpha_k \stackrel{\eqref{zeta_brakets}}{\le} 4\pi KN \lvert \zeta \rvert,
\end{eqnarray*}
where in the second equality we used the fact that $\rho_e(x_k,x_k)=\rho_e(y_k,y_k)=1$ and $\rho_e(x_k,y_k)=0$, thus $\rho_e(y_k+ix_k,y_k+ix_k)=2$. The last statement \emph{(iii)} is then proved by setting $C \coloneqq 4\pi KN$. \qedhere

\label{powerful_lemma}
 Let $(G,d)$ be a simply connected, sub-Riemannian, $2$-step nilpotent Lie group and denote by $\mathfrak{g}$ its associated Lie algebra. Fix a norm $\lvert \cdot \rvert$ on $[\mathfrak{g},\mathfrak{g}]$. Then, there exists $C>0$ such that
 \begin{equation} \label{pitagora_ballbox}
 d(e,q \cdot \exp(\zeta))^2 \le d(e,q)^2 + C \lvert \zeta \rvert, \quad \text{for every $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$.}
 \end{equation}

Thanks to \cref{model}, we can assume $G$ to be as in \eqref{def G} and the sub-Riemannian metric $d$ to be associated with a sub-Riemannian structure $(\Delta,\rho)$ on $G$. We define $V$ as in \eqref{def V}, and we set $C_1$ to be the constant given in \cref{new_lemma} for the norm $\lvert \cdot \rvert$ on $[\mathfrak{g},\mathfrak{g}]$.

Fix $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$. Consider an energy-minimizing curve $\gamma \colon [0,1] \to G$ such that $\gamma(0)=e$ and $\gamma(1)=q$. Let $u \in L^2([0,1],\Delta_e)$ denote the control of $\gamma$. Thanks to \cref{new_lemma}, there exists $v \in L^2([0,1],V)$ such that 
\begin{equation*}
 \gamma_{u+v}(1) = \gamma_u(1) + \zeta \stackrel{\eqref{def G}}{=} q * \exp(\zeta),
 \end{equation*}
 together with
 \begin{equation*}
 \int^1_0 \rho_e(v(t),u(t))\, \mathrm{d} t =0 \quad \text{and} \quad \int^1_0 \rho_e(v(t),v(t))\, \mathrm{d} t = C_1 \lvert \zeta \rvert.
 \end{equation*}
 Therefore, we estimate
 \begin{eqnarray*}
 d(e,q \cdot \exp(\zeta))^2 &\stackrel{\eqref{distance_square}}{\le}& \int^1_0 \rho_e(u(t) + v(t),u(t) + v(t))\, \mathrm{d} t \\
 &=& \int^1_0 \rho_e(u(t),u(t))\, \mathrm{d} t + \int^1_0 \rho_e(v(t),v(t))\, \mathrm{d} t \\
 &=& d(e,q)^2 + C_1 \lvert \zeta \rvert,
 \end{eqnarray*}
 where in the last inequality we used the fact that $u$ is an energy-minimizing control. The statement is then proved by setting $C\coloneqq C_1$.

\label{bounded drift}
 Let $G$ be a $2$-step nilpotent group as in \eqref{def G} and let $(\Delta,\rho)$ be a sub-Riemannian structure on $G$, with $V$ as in \eqref{def V}. Then, there exists $C > 0$ such that, for every energy-minimizing curve $\gamma \colon [0,1] \to G$ with $\gamma(0) = e$, there are $M \in \mathfrak{so}(V)$, $b \in \ker(M)$, $c \in M(V)$, and $\zeta \in [V,V] \cap \Delta$ such that $\sqrt{\rho_e(\zeta,\zeta)}\le C$ and
	\begin{equation} \label{equation_geodesic}
 \gamma(t)= x(t) + \frac{1}{2}\int^t_0 [x(s),\dot{x}(s)] \, \mathrm{d} s + t\zeta, \quad \text{for every $t \in [0,1]$.}
	\end{equation}
 where $x(t) \coloneqq c - e^{tM}c + tb \in V$, for every $t \in [0,1]$.

Fix on $[V,V]$ a norm $\lvert \cdot \rvert$ that extends the restriction of $\sqrt{\rho(\cdot,\cdot)}$ on $\Delta \cap [V,V]$. Let $C_1>0$ be the constant from \cref{powerful_lemma} so that 
 \begin{equation} \label{pitagora_ballbox2}
 d(e,q \cdot \exp(\zeta))^2 \le d(e,q)^2 + C_1 \lvert \zeta \rvert, \quad \text{for every $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$.}
 \end{equation}
Fix $q \in G$ and consider an energy-minimizing curve $\gamma \colon [0,1] \to G$ such that $\gamma(0)=e$ and $\gamma(1)=q$. Let $u \in L^2([0,1],\Delta_e)$ denote the control of $\gamma$.
From \cite[Proposition~7.3.10]{donne2024metricliegroupscarnotcaratheodory}, there are $M \in \mathfrak{so}(V)$, $b \in \ker(M)$, $c \in M(V)$, and $\zeta \in [V,V] \cap \Delta$ such that 
\begin{equation*}
 \gamma(t)= x(t) + \frac{1}{2}\int^t_0 [x(s),\dot{x}(s)] \, \mathrm{d} s + t\zeta, \quad \text{for every $t \in [0,1]$.}
	\end{equation*}
 where $x(t) \coloneqq c - e^{tM}c + tb \in V$, for every $t \in [0,1]$.
We define $u_\infty \in L^2([0,1],V)$ such that, for every $t \in [0,1]$, the value $u_\infty(t)$ is the projection of $u(t)$ on $V$ along $[V,V]$ . We observe that, for every $t \in [0,1]$, we have $\gamma(t)=\gamma_{u_\infty}(t)+t\zeta$. In particular
\begin{equation} \label{point_q_2}
 q = \gamma_{u_\infty}(1) + \zeta = \gamma_{u_\infty}(1) \cdot \exp(\zeta).
\end{equation}
Moreover, since $V$ and $[V,V] \cap \Delta$ are $\rho_e$-orthogonal, we also have
\begin{equation} \label{energy_gamma_2}
 \int^1_0 \rho_e(u(t),u(t))\, \mathrm{d} t =\int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t + \rho_e(\zeta,\zeta).
\end{equation}
We then estimate
\begin{eqnarray*}
 \rho(\zeta,\zeta) &\stackrel{\eqref{energy_gamma_2}}{=}& \int^1_0 \rho_e(u(t),u(t))\, \mathrm{d} t - \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t \\
 &=& d(e,q)^2 - \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t \\
 &\stackrel{\eqref{point_q_2}}{=}& d(e,\gamma_{u_\infty}(1) \cdot \exp(\zeta))^2 - \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t \\
 &\stackrel{\eqref{pitagora_ballbox2}}{\le}& d(e,\gamma_{u_\infty}(1))^2 + C_1\lvert \zeta \rvert - \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t \\
 &\stackrel{\eqref{distance_square}}{\le}& \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t + C_1\lvert \zeta \rvert - \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t
 = C_1\lvert \zeta \rvert,
\end{eqnarray*}
where in the second equality we use the fact that $u$ is an energy-minimizing control. Since $\lvert \cdot \rvert$ coincides with $\sqrt{\rho(\cdot,\cdot)}$ on $\Delta \cap [V,V]$, we get $\rho(\zeta,\zeta) \le C_1 \sqrt{\rho(\zeta,\zeta)}$. We conclude that $\sqrt{\rho(\zeta,\zeta)} \le C_1$. The statement is then proved by setting $C \coloneqq C_1$.

Thanks to \cref{model}, we can assume $G$ to be as in \eqref{def G} and the sub-Riemannian metric $d$ to be associated with a sub-Riemannian structure $(\Delta,\rho)$ on $G$ with $V$ as in \eqref{def V}. Let $d_\infty$ be the canonical asymptotic metric of $d$. Thanks to \cref{powerful_lemma}, there exists $C_1>0$ such that 
 \begin{equation} \label{pitagora_ballbox3}
 d_\infty(e,q \cdot \exp(\zeta))^2 \le d_\infty(e,q)^2 + C_1 \lvert \zeta \rvert, \quad \text{for every $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$.}
 \end{equation}

 Since the metric $d$ is left-invariant, we assume $p$ in \eqref{main equation} to be the identity element $e$. Fix $q \in G$ and consider an energy-minimizing curve $\gamma \colon [0,1] \to G$ such that $\gamma(0)=e$ and $\gamma(1)=q$. Let $u \in L^2([0,1],\Delta_e)$ denote the control of $\gamma$. We define $u_\infty \in L^2([0,1],V)$ such that $u_\infty(t)$ is the projection of $u(t)$ on $V$ parallel to $[V,V]$, for every $t \in [0,1]$. From \cref{bounded drift}, we observe that, for every $t \in [0,1]$, we have $\gamma(t)=\gamma_{u_\infty}(t)+t\zeta$, for some $\zeta \in [\mathfrak{g},\mathfrak{g}]$. In particular
\begin{equation} \label{point_q_3}
 q = \gamma_{u_\infty}(1) + \zeta = \gamma_{u_\infty}(1) \cdot \exp(\zeta).
\end{equation}
From \cref{bounded drift}, there exists $C_2$, independent of $\zeta$, such that
\begin{equation} \label{bound zeta}
 \sqrt{\rho(\zeta,\zeta)} \le C_2.
\end{equation}
Since $\gamma_{u_\infty}$ is a $\Delta_\infty$-horizontal curve, we have
\begin{equation} \label{infinity_eta}
 d_\infty(e,\gamma_{u_\infty}(1))^2 \le \int^1_0 \rho_e(u_\infty(t),u_\infty(t))\, \mathrm{d} t \le \int^1_0 \rho_e(u(t),u(t))\, \mathrm{d} t,
\end{equation}
where in the second inequality we used the fact that $V$ and $[V,V] \cap \Delta$ are $\rho_e$-orthogonal. 

We then estimate
\begin{eqnarray*}
 d_\infty(e,q)^2 &\stackrel{\eqref{point_q_3}}{=}& d_\infty(e, \gamma_{u_\infty}(1) \cdot \exp(\zeta))^2 \\
 &\stackrel{\eqref{pitagora_ballbox3}}{\le}& d_\infty(e, \gamma_{u_\infty}(1))^2 + C_1 \sqrt{\rho(\zeta,\zeta)} \\
 &\stackrel{\eqref{infinity_eta}}{\le}& \int^1_0 \rho_e(u(t),u(t))\, \mathrm{d} t + C_1\sqrt{\rho(\zeta,\zeta)} \\
 &\stackrel{\eqref{bound zeta}}{\le}& d(e,q)^2+ C_1C_2,
\end{eqnarray*}
where in the last inequality we use the fact that $u$ is an energy-minimizing control. Thus, we get a bound on $d_\infty(e,q)^2 - d(e,q)^2$. The bound on $d(e,q)^2 - d_\infty(e,q)^2$ immediately follows from \eqref{obvious bound}. The statement \eqref{main equation} is then proved by setting $C \coloneqq C_1C_2$. 

From \eqref{main equation} we get
\begin{equation} \label{big o estimate}
 \left\lvert d_\infty(p,q) - d(p,q) \right\rvert \le \frac{C}{d_\infty(p,q) + d(p,q)} \quad \text{for every $p,q \in G, \, p \neq q$,}
 \end{equation} 
 which proves \eqref{first consequence}.

\label{bounded distance cor}
In the assumption of \cref{main theorem}, 

 the identity map $\mathrm{id} \colon (G,d) \to (G,d_\infty)$ is a rough isometry.

Clearly, we have 
 \begin{equation*}
 \left\lvert d_\infty(p,q) - d(p,q) \right\rvert \le d_\infty(p,q) + d(p,q) \quad \text{for every $p,q \in G$.}
 \end{equation*}
By combining the previous estimate with \eqref{main equation}, in the form of \eqref{big o estimate}, we obtain, for every $p \neq q$:
\begin{equation*} 
 \left\lvert d_\infty(p,q) - d(p,q) \right\rvert \le \min \Set{\frac{C}{d_\infty(p,q) + d(p,q)},d_\infty(p,q) + d(p,q)} \le \sqrt{C},
\end{equation*}
where in the last inequality we estimated the minimum with the geometric mean. The estimate for $p=q$ is clearly satisfied as well. We conclude that the identity map $(G,d) \to (G,d_\infty)$ is a rough isometry.

\label{same projection}
 Let $G$ be a simply connected, $2$-step nilpotent Lie group, with associated Lie algebra $\mathfrak{g}$, equipped with sub-Riemannian structures $(\Delta,\rho)$ and $(\Delta',\rho')$ such that
 \begin{equation} \label{min bracket generating}
 \Delta_e \oplus [\mathfrak{g},\mathfrak{g}] = \mathfrak{g} \quad \text{and} \quad \Delta'_e \oplus [\mathfrak{g},\mathfrak{g}] = \mathfrak{g}.
 \end{equation}
 Denote by $d$ and $d'$ the sub-Riemannian metrics associated with $(\Delta,\rho)$ and $(\Delta',\rho')$, respectively. Also, denote by $\lVert \cdot \rVert_\mathrm{ab}$ and $\lVert \cdot \rVert'_\mathrm{ab}$ the abelianization norms of $(G,d)$ and $(G,d')$, respectively.
 If $\lVert \cdot \rVert_\mathrm{ab}=\lVert \cdot \rVert'_\mathrm{ab}$, there exists a Lie group morphism $\varphi \in \mathrm{Aut}(G)$ such that the following hold
 \begin{enumerate}[(i)]
 \item $\varphi:(G,d)\to(G,d')$ is an isometry;
 \item $\pi_\mathrm{ab} \circ \varphi = \pi_\mathrm{ab}$, in particular there exists a linear map $L \colon G_\mathrm{ab} \to [\mathfrak{g},\mathfrak{g}]$ such that
 \begin{equation*}
 \varphi(p) = p \cdot \exp\left(L(\pi_\mathrm{ab}(p))\right), \quad \text{for every $p \in G$.}
 \end{equation*}
 \end{enumerate}

\label{equivalence quasi_isometries}
 Let $G$ be a simply connected, $2$-step nilpotent Lie group equipped with two sub-Riemannian structures $(\Delta,\rho)$ and $(\Delta',\rho')$ and denote by $d$ and $d'$ the sub-Riemannian metrics corresponding to $(\Delta,\rho)$ and $(\Delta',\rho')$, respectively. The following are equivalent:
 \begin{enumerate}[(i)]
 \item the two metrics are asymptotic, i.e., $\frac{d'(p,q)}{d(p,q)} \to 1$ as $d(p,q) \to \infty$;
 \item the abelianization norms $\lVert \cdot \rVert_\mathrm{ab}$ and $\lVert \cdot \rVert'_\mathrm{ab}$ of $(G,d)$ and $(G,d')$, respectively, coincides;
 \item the identity map $\mathrm{id} \colon (G,d) \to (G,d')$ is a rough isometry, i.e., there exists $C>0$ such that $$\lvert d(p,q) - d'(p,q) \rvert \le C, \quad \text{for every $p,q \in G$.}$$
 \end{enumerate}

The equivalence $(i)\Leftrightarrow(ii)$ is known to hold for simply connected sub-Finsler nilpotent Lie groups; see \cite[Proposition~3]{MR3153949}. The implication $(iii)\Rightarrow(i)$ is immediate. We now prove that $(i, ii)\Rightarrow(iii)$.

 Denote by $\mathfrak{g}$ the Lie algebra of $G$. Thanks to \cref{bounded distance cor}, it is not restrictive to assume that $d$ and $d'$ are canonical asymptotic metrics, for which \eqref{min bracket generating} is satisfied. From \cref{same projection}, there exists a Lie group morphism $\varphi \in \mathrm{Aut}(G)$ and a linear map $L \colon G_\mathrm{ab} \to [\mathfrak{g},\mathfrak{g}]$ such that
 \begin{align}
 d'(p,q) &= d(\varphi(p),\varphi(q)), \quad \text{for every $p,q \in G$}, \label{phi d}\\
 \varphi(p) &= p \cdot \exp\left(L(\pi_\mathrm{ab}(p))\right), \quad \text{for every $p \in G$.} \label{phi L}
 \end{align}
 Thanks to \cref{powerful_lemma}, there exists $C_1 > 0$ such that 
 \begin{equation} \label{pitagora_ballbox4}
 d(e,q \cdot \exp(\zeta))^2 \le d(e,q)^2 + C_1 \lvert \zeta \rvert, \quad \text{for every $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$.}
 \end{equation}
 We want to bound $\lvert d(p,q) - d'(p,q)\rvert$, since $d$ and $d'$ are both left-invariant, it is not restrictive to consider $p=e$. Fix $q \neq e$ and a norm $\lvert \cdot \rvert$ on $[\mathfrak{g},\mathfrak{g}]$. We estimate
 \begin{eqnarray*}
 d'(e,q)^2 &\stackrel{\eqref{phi d}}{=}& d(\varphi(e),\varphi(q))^2 \\
 &\stackrel{\eqref{phi L}}{=}& d(e,q \cdot \exp\left(L(\pi_\mathrm{ab}(q))\right))^2 \\
 &\stackrel{\eqref{pitagora_ballbox4}}{\le}& d(e,q)^2 + C_1\lvert L(\pi_\mathrm{ab}(q)) \rvert \\
 &\le& d(e,q)^2 + C_1\lVert L \rVert \lvert \pi_\mathrm{ab}(q) \rvert \\
 &\le& d(e,q)^2 + C_1 \lVert L \rVert d(e,q),
 \end{eqnarray*}
where $\lVert L \rVert$ denotes the operator norm of $L \colon (G_\mathrm{ab},\lVert \cdot \rVert_\mathrm{ab}) \to ([\mathfrak{g},\mathfrak{g}],\lvert \cdot \rvert)$ and in the last inequality we used the fact that $\pi_\mathrm{ab}$ is a submetry. We obtain
\begin{equation} 
 d'(e,q)^2 \le d(e,q)^2 + C_1 \lVert L \rVert d(e,q) \le (d(e,q)^2 + C_1 \lVert L \rVert)^2,
\end{equation}
and therefore $d'(e,q) - d(e,q) \le C_1 \lVert L \rVert$.



Similarly, thanks to \cref{powerful_lemma}, there exists $C_2 > 0$ such that 
 \begin{equation*} 
 d'(e,q \cdot \exp(\zeta))^2 \le d'(e,q)^2 + C_2 \lvert \zeta \rvert, \quad \text{for every $q \in G$ and $\zeta \in [\mathfrak{g},\mathfrak{g}]$.}
 \end{equation*}
 An analogous argument shows that $d(e,q) - d'(e,q) \le C_2 \lVert L \rVert$. The statement is then proved by setting $C \coloneqq \max\set{C_1,C_2} \lVert L \rVert$.

\label{prop_rate_convergence}
 Let $(G,d)$ be a simply connected $2$-step nilpotent sub-Riemannian Lie group and denote by $(\widehat{G},\widehat{d})$ its asymptotic cone. Then
 \begin{equation} \label{rate_convergence}
 d_{GH}\left((G,\tfrac{1}{n}d),(\widehat{G},\widehat{d})\right) = O(n^{-1}), \quad \text{as $n \to\infty$,}
 \end{equation}
 where $d_{GH}$ denotes the Gromov-Hausdorff distance.

Let $(G,d)$ be as in the statement and denote by $(G,d_\infty)$ its canonical asymptotic metric, defined in \eqref{asymptotic metric}. As discussed in \cref{section_asymptotic_metric}, $(G,d_\infty)$ is isometric to the asymptotic cone $(\widehat{G},\widehat{d})$ of $(G,d)$. From \cref{bounded distance cor}, there exists $C>0$ such that
\begin{equation*}
 \left\lvert \frac{1}{n}d_\infty(p,q) - \frac{1}{n}d(p,q) \right\rvert \le \frac{C}{n} \quad \text{for every $p,q \in G$, and $n \in \mathbb N$.}
\end{equation*}
Thus, we infer (see \cite[Corollary 7.3.28]{MR1835418}) that
\begin{equation} \label{gh_inequality1}
 d_{GH}\left((G,\tfrac{1}{n}d),(G,\tfrac{1}{n}d_\infty)\right) \le \frac{2C}{n}.
 \end{equation}
We recall that $(G,d_\infty)$ is a Carnot metric and therefore it is self-similar, i.e., $(G,d_\infty)$ is isometric to $(G,\lambda d_\infty)$ for every $\lambda > 0$. We conclude that $(G,\tfrac{1}{n}d_\infty)$ is isometric to $(\widehat{G},\widehat{d})$. We have proved \eqref{rate_convergence}.

The \emph{Engel group} $\mathbb E$ is the simply connected Lie group whose associated Lie algebra $\mathfrak{g}$ admits a basis $\set{X_1,X_2,Y,Z}$ such that the only non-trivial bracket relations between elements of the basis are
 \begin{equation*}
 [X_1,X_2]=Y, \qquad [X_1,Y]=Z.
 \end{equation*}
 We consider the left-invariant Riemannian metric $d$ on $\mathbb E$ such that $\set{X_1,X_2,Y,Z}$ is an orthonormal frame for the metric tensor. Since $[\mathfrak{g},\mathfrak{g}]=\mathrm{span}\set{Y,Z}$, we get that the canonical asymptotic metric $d_\infty$ associated with $d$ is the metric $d_\infty$ induced by the sub-Riemannian structure $(\Delta,\rho_{|\Delta})$, where
 \begin{equation*}
 \Delta = \bigcup_{p \in \mathbb E} \mathrm{span}\set{\mathrm{d} L_p(X_1), \mathrm{d} L_p(X_2)}.
 \end{equation*}
 We identify $\mathbb E$ and $\mathbb R^4$ with the global diffeomorphism
 \begin{equation*}
 \Phi \colon \mathbb R^4 \to \mathbb E, \quad (x_1,x_2,y,z) \mapsto \exp(x_1X_1+x_2X_2+yY+zZ).
 \end{equation*}
 With this identification, we define $p_n \coloneqq (0,n,0,\sqrt{n}) \in \mathbb E$ for every $n \in \mathbb N$. By considering the straight line $\gamma_n(t)\coloneqq(0,tn,0,t\sqrt{n})$, we get the estimate
 \begin{equation} \label{d_riemannian}
 d(e,p_n) \le \sqrt{n^2 + n} \le n + \tfrac{1}{2}.
 \end{equation}
 We stress that $(\mathbb E,d_\infty)$ is self-similar, in particular
 \begin{equation} \label{dilation_engel}
 d_\infty(e,(x_1,x_2,y,z)) = \lambda d_\infty(e,(\lambda^{-1} x_1, \lambda^{-1} x_2, \lambda^{-2} y, \lambda^{-3} z)), \quad \text{for every $(x_1,x_2,y,z) \in \mathbb R^4, \, \lambda \ge 0$.}
 \end{equation}
 Moreover, from \cite[Lemma~4.1]{MR3906166}, there exists $C>0$ such that
 \begin{equation} \label{cusp_engel}
 d_\infty(e,(0,1,0,\varepsilon)) \ge 1 + C\varepsilon^{1/3}, \quad \text{for every $\varepsilon \in [0,1)$.}
 \end{equation}
 Therefore, we get the estimate
 \begin{equation*}
 d_\infty(e,p_n) \stackrel{\eqref{dilation_engel}}{=} n d_\infty(e,(0,1,0,n^{-\frac{5}{2}})) \stackrel{\eqref{cusp_engel}}{\ge} n (1 + Cn^{-\frac{5}{6}})
 = n + Cn^{\frac{1}{6}}.
 \end{equation*}
 By comparing it with \eqref{d_riemannian}, we get
 \begin{equation*}
 \lvert d_\infty(e,p_n)-d(e,p_n)\rvert \ge Cn^{\frac{1}{6}} - \tfrac{1}{2} \to \infty, \quad \text{as $n \to \infty$.}
 \end{equation*}

\label{error_term}
 Let $(G,d, \mathrm{vol})$ be a metric measure space such that for some $e\in G$ and $C,Q, r_0>0$ we have
 \begin{equation}\label{homog_meas}
 \mathrm{vol}(B(e, r))=Cr^Q, \quad \text{for every $r \ge r_0$.}
 \end{equation}
 Consider on $G$ a distance function $d'$ such that for some function $f(r) = O(r)$ as $r \to \infty$ we have
 \begin{equation} \label{error_distance}
 \lvert d(e,p) - d'(e,p) \rvert \le f(d(e,p)), \quad \text{for every $p \in G$}.
 \end{equation}
 Denote by $B(r)$ and $B'(r)$ the balls of radius $r$, centered at $e$, for the distance functions $d$ and $d'$, respectively. We claim that
 \begin{equation*}
 \mathrm{vol}(B'(r)) = Cr^Q + O(r^{Q-1}f(r)), \quad \text{as $r\to \infty$.}
 \end{equation*}

 Indeed, from \eqref{error_distance}, we get
 \begin{equation*}
 B(r-f(r)) \subseteq B'(r) \subseteq B(r + f(r)), \quad \text{for every $r \ge 0$,},
 \end{equation*}
 and consequently from \eqref{homog_meas} we deduce 
 \begin{equation*}
 Cr^Q + O(r^{Q-1}f(r)) = C(r-f(r))^Q \le \mathrm{vol}(B'(r)) \le C(r+f(r))^Q = Cr^Q + O(r^{Q-1}f(r)),
 \end{equation*}
 where in the equalities we have used $f(r) = O(r)$, as $r \to \infty$.

\label{asymptotic_sphere}
 Let $(G,d)$ be a simply connected $2$-step nilpotent sub-Riemannian Lie group and fix a Haar measure $\mathrm{vol}$ on $G$. For every $r \ge 0$, denote by $B(r) \subseteq G$ the metric ball of radius $r$, centered at the identity element of $G$. Then the following holds:
 \begin{enumerate}[(i)]
 \item there exists $C > 0$ such that
 \begin{equation*}
 \mathrm{vol}(B(r)) = C r^Q + O(r^{Q-2}), \quad \text{as $r \to \infty$,}
 \end{equation*}
 where $Q$ is the Hausdorff dimension of the asymptotic cone of $(G,d)$,
 \item if $\mathrm{vol}(B(r)) = C r^Q + o(r^{Q-2})$, as $r \to \infty$, then the metric Lie group $(G,d)$ coincides with its canonical asymptotic metric. In particular $\mathrm{vol}(B(r)) = C r^Q$.
 \end{enumerate}

Let $d_\infty$ be the canonical asymptotic metric of $(G,d)$. 

 We denote by $B_\infty(r)$ the metric ball of radius $r$ with respect to the distance function $d_\infty$, centered at the identity element of $G$. 

Note that, being $(G,d_\infty)$ a Carnot group,
 we have 
 \begin{equation} \label{volume_spheres}
     \mathrm{vol}(B_{\infty}(r))=Cr^Q, \quad \text{for every $r \ge 0$,}
 \end{equation}
 where $Q$ is the Hausdorff dimension of $(G,d_\infty)$ and $C \coloneqq \mathrm{vol}\left(B_{\infty}(1)\right)$.
 Moreover, by \cref{main theorem}, we have \eqref{first consequence}. 
 Hence, we are in the setting of \cref{error_term} with $f(r)= O(1/r)$. 
 Therefore, we conclude 
 \begin{equation*}
 \mathrm{vol}(B(r)) = Cr^Q + O(r^{Q-1}\cdot r^{-1}) = Cr^Q + O(r^{Q-2}),
 \end{equation*}

 We thus proved (i).













 To prove (ii), assume that $(G,d)$ does not coincide with its canonical asymptotic metric $(G,d_\infty)$. Denote by $\mathfrak{g}$ the Lie algebra of $G$, and by $(\Delta,\rho)$ and $(\Delta_\infty,\rho)$ the sub-Riemannian structures of $(G,d)$ and $(G,d_\infty)$, respectively. Since $d$ is not a canonical asymptotic metric, there exists $w \in \Delta \cap [\mathfrak{g},\mathfrak{g}]$ such that $\rho(w,w)=1$. Let $W$ be the one-parameter subgroup generated by $w$. Since $W$ is a normal subgroup of $G$, we have the manifold identification 
 \begin{equation*}
 G \cong G/W \times W.
 \end{equation*}
 We recall from \cite[Proposition~7.1.9]{donne2024metricliegroupscarnotcaratheodory} that there exists a sub-Finsler metric $d'$ on $G/W$ such that the projection map $\pi \colon (G,d_\infty) \to (G/W,d')$ is a submetry. We denote by $B'(r)$ the metric ball of radius $r$ with respect to the distance function $d'$, centered at the identity element of $G/W$.

 We write the Haar measure $\mathrm{vol}$ on $G$ as the product measure of a Haar measure $\mu$ on $G/W$ and the Lebesgue measure on $W = \set{\exp(tw) \colon t \in \mathbb R} \cong \mathbb R$. We point out that, since $(G,d_\infty)$ is self-similar, then $(G/W, d')$ is self-similar as well, and that its Hausdorff dimension is $Q-2$; see \cite[Corollary~4.3.6]{donne2024metricliegroupscarnotcaratheodory}. Therefore, there exists $C'>0$ such that
 \begin{equation} \label{volume_proj}
 \mu \left(B'(r) \right) = C' r^{Q-2}, \quad \text{for every $r \ge 0$.}
 \end{equation}

 Next, for every $k,r \ge 0$, we define
 $E_{k,r} \coloneqq \set{ p + \lambda w \colon p \in B_\infty\left( r - \tfrac{k^2}{r}\right), \, \lambda \in [-k,k] } \subseteq G$, and we claim that
 \begin{equation} \label{inclusion_spheres}
 E_{k,r} \subseteq B(r), \quad \text{for every $k \ge 0$ and $r \ge k$.}
 \end{equation}
 Indeed, fix $p \in B_\infty\left( r - \tfrac{k^2}{r}\right)$ and $\lambda \in [-k,k]$. Consider a $\Delta_\infty$-horizontal curve $\gamma_u \colon [0,1] \to G$, from $e$ to $p$, such that $\int^1_0 \rho(u,u) \, \mathrm{d} t \le \left(r - \frac{k^2}{r}\right)^2$. Then $\gamma_{u+\lambda w}$ is a $\Delta$-horizontal curve and
 \begin{align*}
 \int^1_0 \rho(u+\lambda w, u+\lambda w) \, \mathrm{d} t = \int^1_0 \rho(u,u) \, \mathrm{d} t + \lambda^2 \le \left(r - \frac{k^2}{r}\right)^2 + k^2 = r^2 - k^2 + \frac{k^4}{r^2} \le r^2,
 \end{align*}
 where in the first equality we used \eqref{def V}, and in the last inequality we used that $r \ge k$.
 We conclude that $p+\lambda w = \gamma_{u+\lambda w}(1) \in B(r)$, and the inclusion \eqref{inclusion_spheres} is proved.

 We set $k \coloneqq \frac{C'}{QC}$. For $r \ge k^2$, we estimate
 \begin{eqnarray*}
 \mathrm{vol}(B(r)) \stackrel{\eqref{inclusion_spheres}}{\ge} \mathrm{vol}(E_{k,r}) &=& \mathrm{vol}\left(B_\infty\left( r - \tfrac{k^2}{r}\right)\right) + 2k\mu\left(B'\left( r - \tfrac{k^2}{r}\right)\right) \\
 &\stackrel{\eqref{volume_spheres}\eqref{volume_proj}}{=}& C\left( r - \tfrac{k^2}{r}\right)^Q + 2kC'\left( r - \tfrac{k^2}{r}\right)^{Q-2} \\
 &=& C(r^Q - Qk^2 r^{Q-2} + o(r^{Q-2})) + 2kC'(r^{Q-2} + o(r^{Q-2})) \\
 &=& Cr^Q + k(2C' - kQC)r^{Q-2} + o(r^{Q-2}) \\
 &=& Cr^Q + kC'r^{Q-2} + o(r^{Q-2}),
 \end{eqnarray*}
 where in the first equality we used the definition of $E_{k,r}$ and we wrote $\mathrm{vol}$ as the product measure of $\mu$ with the Lebesgue measure on $W$. We infer that $\mathrm{vol}(B(r)) - Cr^Q \notin o(r^{Q-2})$ and the proof of (ii) is concluded.

\label{sharpness}
 Let $(G,d)$ be a sub-Riemannian, $2$-step nilpotent Lie group, and denote by $d_\infty$ its canonical asymptotic metric. If
 \begin{equation*}
 \lvert d_\infty(p,q)^2 - d(p,q)^2 \rvert \to 0, \quad \text{as $d(p,q) \to \infty$.}
 \end{equation*}
 then $d=d_\infty$.

From the assumption, we get 
 $ \lvert d_\infty(e,p) - d(e,p) \rvert = o(1/d(e,p)) $, as $d(e,p)\to \infty$.
 By \cref{error_term},

we get
 \begin{equation*}
 \mathrm{vol}(B(r)) = C r^Q + o(r^{Q-2}), \quad \text{as $r\to \infty$.}
 \end{equation*}
 Thanks to (ii) in \cref{asymptotic_sphere}, we infer that $d=d_\infty$.

\label{prop_linf}
 Let $(\mathbb H,d)$ be the sub-Riemannian Heisenberg group with sub-Riemannian structure $(\Delta,\rho)$. For $v \in \mathfrak{h}$, we define the norm
 \begin{equation} \label{linf_norm}
 \lVert v \rVert \coloneqq \max \Set{ \sqrt{\rho(v_h,v_h)}, \lvert \lambda \rvert}, 
 \end{equation}
 where we write $v = v_h + \lambda Z$, with $v_h \in \mathrm{span} \set{X,Y}$ and $\lambda\in \mathbb R$. Denote by $d_F$ the Finsler distance function associated with the Finsler norm \eqref{linf_norm}, and by $B_F(r)$ the ball of radius $r$ with respect to the distance function $d_F$, centered at the identity element of $\mathbb H$. Fix a Haar measure $\mathrm{vol}$ on $\mathbb H$, then there exists $C,D > 0$ such that
 \begin{equation} \label{polinomial inf}
 \mathrm{vol} \left(B_F(r)\right) = Cr^4 + Dr^3, \quad \text{for every $r \ge 0$.}
 \end{equation}

Denote by $B(r)$ the ball of radius $r$ with respect to the sub-Riemannian distance function $d$, centered at the identity element $e$ of $\mathbb H$. We claim that, for every $r \ge 0$, we have 
 \begin{equation} \label{equality_balls}
 B_F(r)= \set{p+ \lambda Z \,\colon \, p \in B(r), \, \lambda \in [-r,r]}.
 \end{equation}
 Indeed, fix $p \in B(r)$ and $\lambda \in [-r,r]$. Consider an energy-minimizing, $\Delta$-horizontal curve $\gamma_u \colon [0,1] \to \mathbb H$ from $e$ to $p$. We get that $\sqrt{\rho(u(t),u(t))}\equiv c$ for some constant $c \le r$. We consider the control $\widetilde{u} \colon [0,1] \to \mathfrak{h}$ defined as $\widetilde{u}(t)=u(t) + \lambda Z$. From \cref{lemma integral}, we get that $\gamma_{\tilde{u}}(1) = p + \lambda Z$. Moreover
 \begin{equation*}
 \int^1_0 \lVert u(t) \rVert \, \mathrm{d} t = \int^1_0 \max \Set{\sqrt{\rho(u(t),u(t))}, \lvert \lambda \rvert} \, \mathrm{d} t \le \max \Set{c, \lvert \lambda \rvert}\le r.
 \end{equation*}
 This proves that $\set{p+zZ \,\colon \, p \in B(r), \, \lambda \in [-r,r]} \subseteq B_F(r)$. For the opposite inclusion, fix $q \in B_F(r)$ and consider a curve $\gamma_u \colon [0,1] \to \mathbb H$ such that $\int^1_0 \lVert u(t) \rVert \, \mathrm{d} t \le r$. 
 For every $t \in [0,1]$, we write $u(t) = u_h(t) + \lambda(t) Z$. In particular, $\gamma_{u_h}$ is a $\Delta$-horizontal curve and 
 \begin{equation*}
 \int^1_0 \sqrt{\rho(u_h(t),u_h(t))} \, \mathrm{d} t \le \int^1_0 \lVert u(t) \rVert \, \mathrm{d} t \le r,
 \end{equation*}
 which implies $\gamma_{u_h}(1) \in B(r)$. From \cref{lemma integral}, we get $q = \gamma_{u_h}(1) + \left(\int^1_0 \lambda(t) \mathrm{d} t\right)Z$. The proof of \eqref{equality_balls} is concluded by estimating
 \begin{equation*}
 \left\lvert \int^1_0 \lambda(t) \, \mathrm{d} t \right\rvert \le \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t \le \int^1_0 \lVert u(t)\rVert \, \mathrm{d} t \le r.
 \end{equation*}

 Next, we recall that the Haar measure $\mathrm{vol}$ on $\mathbb H$ is a multiple of the Lebesgue measure $\mathscr{L}^3$ on $\mathfrak{h} = \mathrm{span}\set{X,Y,Z} \cong \mathbb R^3$. Moreover, the projection map $\pi \colon \mathfrak{h} \to \mathrm{span}\set{X,Y}$, parallel to $Z$, is a submetry between $(\mathbb H,d)$ and the Euclidean distance on $\mathrm{span}\set{X,Y} \cong \mathbb R^2$; see \cite[Proposition~7.1.9]{donne2024metricliegroupscarnotcaratheodory}. Finally, for $r \ge 0$, we compute
 \begin{eqnarray*}
 \mathrm{vol}(B_F(r)) &\stackrel{\eqref{equality_balls}}{=}& 
 \mathrm{vol} \left( \set{p+\lambda z \,\colon \, p \in B(r), \, \lambda \in [-r,r]} \right) \\
 &=& \mathrm{vol}(B(r)) + 2r \mathscr{L}^2(\pi(B(r))) \\
 &=& Cr^4 + Dr^3, 
 \end{eqnarray*}
 for some $C,D>0$.

Assume that there exists a Carnot metric $d$ such that $\lvert d(p,q) - d_F(p,q) \rvert \to 0$, as $d(p,q) \to \infty$.
 Then, by \cref{error_term},

 we get
 \begin{equation*}
 \mathrm{vol}(B_F(r)) = C r^4 + o(r^3), \quad \text{as $r\to \infty$,}
 \end{equation*}
 which is in contradiction with \eqref{polinomial inf}.

\label{prop_ellone}
 Let $(\mathbb H,d)$ be the sub-Riemannian Heisenberg group with sub-Riemannian structure $(\Delta,\rho)$. For $v \in \mathfrak{h}$, we define the norm
 \begin{equation} \label{lone_norm}
 \lVert v \rVert \coloneqq \sqrt{\rho(v_h,v_h)}+ \lvert \lambda \rvert, 
 \end{equation}
 where we write $v = v_h + \lambda Z$, with $v_h \in \mathrm{span} \set{X,Y}$ and $\lambda\in\mathbb R$. Denote by $d_F$ the Finsler distance function associated with the Finsler norm \eqref{lone_norm}, and by $B_F(r)$ the ball of radius $r$ with respect to the distance function $d_F$, centered at the identity element of $\mathbb H$. Fix a Haar measure $\mathrm{vol}$ on $\mathbb H$, then there exists $r_0 > 0$ such that
 \begin{equation*}
 d(p,q) = d_F(p,q), \quad \text{for every $p,q \in \mathbb H$ such that $d(p,q)\ge r_0$.}
 \end{equation*}
 In particular, there exists $C>0$ such that $\mathrm{vol}(B_F(r))=Cr^4$ for every $r \ge r_0$.

Since both metrics $d$ and $d_F$ are left-invariant, it is not restrictive to assume $p=e$.
 Let us consider the projection map $\pi \colon \mathbb H \to \mathrm{span}\set{X,Y}$, parallel to $Z$. From the complete description of geodesics in the sub-Riemannian Heisenberg group (see \cite[Section~2.4.1]{donne2024metricliegroupscarnotcaratheodory}), there exists $c>0$ such that for every $q \in \mathbb H$ and every $d$-minimizing curve $\gamma \colon [0,1] \to \mathbb H$, from $e$ to $q$, we get
 \begin{equation} \label{existence_time}
 \lVert \pi(\gamma(t_0)) \rVert = c \cdot d(e,q), \quad \text{for some $0 \le t_0 \le 1$.}
 \end{equation}
 Fix $q \in \mathbb H$ such that $d_F(e,q) \ge 3c^{-1} + d(e,Z)^2$, and consider a $d_F$-minimizing curve $\gamma_u \colon [0,1] \to \mathbb H$ from $e$ to $q$. For every $t \in [0,1]$, we write $u(t) = u_h(t) + \lambda(t) Z$. From \cref{lemma integral}, we get 
 \begin{equation*}
 q = \gamma_{u_h}(1) + \int^1_0 \lambda(t) \, \mathrm{d} t \cdot Z.
 \end{equation*}
 Moreover, since $\gamma_u$ is length-minimizing, we get
 \begin{equation} \label{lengu}
 \ell(\gamma_u) \stackrel{\eqref{lone_norm}}{=} \int^1_0 \sqrt{\rho(u_h(t),u_h(t))} \, \mathrm{d} t + \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t = d_F(e,q) \ge 3c^{-1} + d(e,Z)^2.
 \end{equation}
 First, we claim that \begin{equation} \label{first_claim}
 \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t \le d(e,Z)^2. 
 \end{equation}
 Indeed, assume that $d(e,Z)^2 < \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t $. Then, we estimate
 \begin{equation*}
 d\left(e, \left(\int^1_0 \lambda(t) \, \mathrm{d} t \right) Z\right) = \sqrt{\left\lvert \int^1_0 \lambda(t) \, \mathrm{d} t \right\rvert} \cdot d(e,Z) < \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t,
 \end{equation*}
 where in the equality we used that the metric space $(\mathbb H,d)$ is self-similar. The latter estimate implies that there exists a $\Delta$-horizontal curve $\gamma_{v} \colon [0,1] \to \mathbb H$, from $e$ to $\left(\int^1_0 \lambda(t) \, \mathrm{d} t \right) Z$ such that $\ell(\gamma_{v}) < \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t$. Then, we consider the control $\widetilde{u} \colon [0,2] \to \mathfrak{h}$ defined by 
 \begin{equation*}
 \widetilde{u}(t) = \begin{cases}
 u(t) & \text{if $0\le t \le 1$,} \\ v(t-1) & \text{if $1<t\le2$.}
 \end{cases}
 \end{equation*}
 From \cref{lemma integral}, we get $\gamma_{\tilde{u}}(2) = \gamma_{u_h}(1) + \left(\int^1_0 \lambda(t) \, \mathrm{d} t \right) Z =q$. Moreover, we obtain
 $$\ell(\gamma_{\tilde{u}}) = \ell(\gamma_{u_h}) + \ell(\gamma_v) < \int^1_0 \sqrt{\rho(u_h(t),u_h(t))} \, \mathrm{d} t + \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t \stackrel{\eqref{lengu}}{=} \ell(\gamma_u),$$
 contradicting the minimality of $\gamma_u$. We thus proved \eqref{first_claim}. Consequently, thanks to \eqref{lengu}, we infer that $\ell(\gamma_{u_h}) \ge 3c^{-1}$.

 Next, we claim that $\gamma_{u_h}$ is a $d$-minimizing curve. Indeed, assume that there exists a $\Delta$-horizontal curve $\gamma_{u_h'}$ such that $\gamma_{u_h'}(1) = \gamma_{u_h}(1)$ and $\ell(\gamma_{u_h'}) < \ell(\gamma_{u_h})$. Then, the control $u' \colon [0,1] \to \mathfrak{h}$ defined by $u'(t) := u_h'(t) + \lambda(t)Z$ would satisfy $\gamma_{u'}(1)=q$ and $\ell(\gamma_{u'})<\ell(\gamma_u)$, contradicting the minimality of $\gamma_u$. We thus proved that $\gamma_{u_h}$ is $d$-minimizing and in particular $d(e,\gamma_{u_h}(1))= \ell(\gamma_{u_h}) \ge 3c^{-1}$.

 From \eqref{existence_time}, there exists $0 \le t_0 \le 1$ such that
 \begin{equation} \label{grater3}
 \lVert \pi(\gamma_h(t_0)) \rVert = c \cdot d(e,\gamma_h(1)) \ge 3.
 \end{equation}
 Let $w \in \mathrm{span}\set{X,Y}$ be such that $\rho(w,\pi(\gamma_h(t_0)))=0$ and $[w,\pi(\gamma_h(t_0))] = \left(\int^1_0 \lambda(t) \, \mathrm{d} t\right)Z$. We thus obtain 
 \begin{equation} \label{product_norm}
 \lVert w \rVert \cdot \lVert \pi(\gamma_h(t_0)) \rVert = \left\lvert \int^1_0 \lambda(t) \, \mathrm{d} t \right\rvert.
 \end{equation}
 We then consider the control $\widehat{u} \colon [0,3] \to \mathfrak{h}$ defined by
 \begin{equation*}
 \widehat{u}(t) = \begin{cases}
 w & \text{if $0 \le t \le 1$,} \\ u(t-1) & \text{if $1 < t \le 1+t_0 $,} \\ -w & \text{if $1+t_0 < t \le 2+t_0$,} \\ u(t-2) & \text{if $2+t_0 < t \le 3$.}
 \end{cases}
 \end{equation*}
Note that the curves $\gamma_{\hat{u}}$ and $\gamma_u$ have the same endpoints. We then estimate
 \begin{eqnarray*}
 \ell(\gamma_{\hat{u}}) &=& \ell(\gamma_{u_h}) + 2 \lVert w \rVert \\
 &\stackrel{\eqref{product_norm}}{=}& \ell(\gamma_{u_h}) + 2\frac{\left\lvert \int^1_0 \lambda(t) \, \mathrm{d} t \right\rvert}{\lVert \pi(\gamma_h(t_0)) \rVert} \\
 &\stackrel{\eqref{grater3}}{\le}& \ell(\gamma_{u_h}) + \frac{2}{3} \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t \\
 &\le& \ell(\gamma_{u_h}) + \int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t = \ell(\gamma_u).
 \end{eqnarray*}
 From the minimality of $\gamma_u$, we get that $\ell(\gamma_{\hat{u}})=\ell(\gamma_u)$ and all inequalities in the previous estimates are equalities. In particular $\int^1_0 \lvert \lambda(t) \rvert \, \mathrm{d} t = 0$ and therefore $\gamma_u$ is a $\Delta$-horizontal curve. We conclude that $d(e,q)=d_F(e,q)$ and the statement is proved by setting $r_0 \coloneqq 3c^{-1} + d(e,Z)^2$.

We consider the left-invariant Riemannian metric $d_R$ on the Heisenberg group $\mathbb H$ such that $\set{X,Y,Z}$ is an orthonormal frame for the metric tensor $\rho$. We fix $r > 0$ and we study the volume of the metric ball
 \begin{equation*}
 B(r) \coloneqq \set{ p \in \mathbb H \, \colon \, d_R(e,p) \le r}.
 \end{equation*}

 We identify $\mathbb H$ with $\mathbb R^3$ with the global diffeomorphism
 \begin{equation*}
 \Phi \colon \mathbb R^3 \to \mathbb H, \quad (x,y,z) \mapsto \exp(xX + yY + zZ).
 \end{equation*}
 We remark that the pushforward by $\Phi$ of the Lebesgue measure on $\mathbb R^3$ is a Haar measure on $\mathbb H$.

 With this identification, the function $f \coloneqq d(e,\cdot)$ has a rotational symmetry around the $Z$ axis and a reflectional symmetry along the $XY$ plane. Therefore $B(r)$ is completely determined by 
 \begin{equation*}
 E(r) \coloneqq \set{(x,0,z) \in \mathbb R^3 \, \colon x,z>0, \, d_R(e,(x,0,z))=r}.
 \end{equation*}
 As a consequence of the explicit integration of the geodesic equations \cite[Proposition 5.4]{MR3673666}, every point $p \in E(r)$ is reached by a unique length-minimizing curve from the identity element $e=(0,0,0)$, and such curve is of the form $\gamma_p =(x_p,y_p,z_p) \colon [0,t_p] \to \mathbb R^3$, where
 \begin{equation*}
 \begin{cases}
 x_p(t)=\frac{1}{k_p}\left((\cos \theta_p(\cos(k_pt)-1) - \sin \theta_p \sin(k_pt)\right) ,\\
 y_p(t)=\frac{1}{k_p}\left((\sin \theta_p(\cos(k_pt)-1) + \cos \theta_p \sin(k_pt)\right) ,\\
 z_p(t)= \frac{t}{2k_p}-\frac{1}{2k_p^2}\sin(k_pt)+k_pt \,,
 \end{cases}
 \end{equation*}
 for some $k_p>0$, $0 \le \theta_p < \pi$, and $0 < t_p < \frac{2\pi}{k_p}$. Therefore, we get
 \begin{equation*}
 p = \left(\frac{\sqrt{2-2\cos(k_pt_p)}}{k_p}, 0, \frac{k_pt_p - \sin(k_pt_p)}{2k_p^2}+k_pt_p\right).
 \end{equation*}
We observe that $\gamma_p$ is parametrized with constant speed $\sqrt{1+k_p^2}$, thus we require $t_p\sqrt{1+k_p^2}=r$.

 We set $\alpha_p \coloneqq k_p t_p$. The condition $0 < t_p < \frac{2\pi}{k_p}$ implies $\alpha_p < 2 \pi$, whilst the condition $t_p\sqrt{1+k_p^2}=r$ implies $\alpha_p < r$. Vice-versa, we claim that for every $0 < \alpha < \min\set{2 \pi, r}$, there exists a unique $k>0$ and $0 < t < \frac{2\pi}{k}$ such that $kt=\alpha$ and $t\sqrt{1+k^2}=r$. Indeed, after some easy computations, these two conditions are equivalent to
 \begin{equation*}
 \frac{k}{\sqrt{1+k^2}}=\frac{\alpha}{r}, \quad t=\sqrt{r^2-\alpha^2},
 \end{equation*}
 which admit unique solutions $k,t>0$, since $\alpha < r$. Moreover, since $\alpha < 2 \pi$, we get $t < \frac{2 \pi}{k}$.

 We conclude that the curve $p \coloneqq (0,\min\set{2 \pi,r}) \to \mathbb R^3$, defined by setting
 \begin{equation*}
 p(\alpha) \coloneqq \left(\frac{\sqrt{r^2-\alpha^2}\sqrt{2-2\cos(\alpha)}}{\alpha},0,\frac{(r^2-\alpha^2)(\alpha-\sin(\alpha))}{2\alpha^2}+\alpha \right),
 \end{equation*}
 parametrizes the set $E(r)$.

 The volume $V(r)$ of the ball $B(r)$ is therefore twice the volume of the solid of revolution with profile $p(\alpha)$ around the $Z$ axis. Thus
 \begin{equation*}
 V(r) = 2 \pi \int_0^{\min\set{2\pi,r}} x(\alpha)^2 \frac{\partial z(\alpha)}{\partial \alpha} \, \mathrm{d} \alpha .
 \end{equation*}
 After some straightforward computations, we finally get
 \begin{align*}
 V(r) &= 2 \pi r^4 \int_0^{\min\set{2\pi,r}} \frac{1-\cos(\alpha)}{\alpha^2}\cdot \frac{2\sin(\alpha)-\alpha\cos(\alpha)-\alpha}{\alpha^3} \, \mathrm{d} \alpha \\ 
 & + 2 \pi r^2 \int_0^{\min\set{2\pi,r}} \frac{\sin^2(\alpha)}{\alpha^2} - \frac{(1 - \cos(\alpha))(2\sin(\alpha)-\alpha\cos(\alpha)-\alpha)}{\alpha^3} \, \mathrm{d} \alpha \\
 & - 2 \pi \int_0^{\min\set{2\pi,r}} \sin^2(\alpha) \, \mathrm{d} \alpha .
 \end{align*}
 We stress that, as expected $V(r)=O(r^3)$, as $r \to 0$. Whilst for $r \ge 2 \pi$, we get \eqref{volume_heis}
 for some $C_0,C_2,C_4 \neq 0$.

\label{bounded iso}
 Let $(G,d)$ be a simply connected, nilpotent, metric Lie group for which all bounded sets are precompact. Let $\varphi$ be an automorphism of $G$ such that $\varphi_\mathrm{ab}=\mathrm{id}$. The following are equivalent:
 \begin{enumerate}[(i)]
 \item $\varphi$ is at bounded distance from an isometry of $(G,d)$,
 \item $\varphi=C_g$ for some $g \in G$, where $C_g$ is defined by $C_g \colon h \mapsto ghg^{-1}$.
 \end{enumerate}

Assume $\varphi(p) \neq \psi(p)$ for some $p \in G$. 
 Consider the function $n\in \mathbb N \mapsto \varphi(p)^{-n}\psi(p)^n$, in exponential coordinates. By Baker-Campbell-Hausdorff formula (see \cite[Theorem~11.2.6]{hilgert2011structure}), 
 this function is a polynomial. Moreover, it is not constant since it has different values at $n=0$ and $n=1$.
 Consequently, it diverges as $n$ goes to infinity.
 By the assumption on $(G,d)$ the set is unbounded with respect to the distance $d$, therefore 
 \begin{equation*}
 d(\varphi(p^n),\psi(p^n)) = d( e , \varphi(p)^{-n}\psi(p)^n) \to \infty, \quad \text{ as $n \to \infty$.}
 \end{equation*}
 Thus, we proved that the automorphisms $\varphi$ and $\psi$ are not at bounded distance.

First, assume that $\varphi=C_g$, for some $g \in G$. Then $\varphi$ is the composition of the map $L_g$, which is an isometry, and the right-translation $R_g$, which is at bounded distance from the identity map. We conclude that $\varphi$ is at bounded distance from the isometry $L_g$.

 Conversely, assume that $\varphi$ is at bounded distance from an isometry $f \colon (G,d) \to (G,d)$, i.e., there exists $C>0$ such that
 \begin{equation} \label{bounded 1}
 d(f(p),\varphi(p)) \le C, \quad \text{for every $p \in G$.}
 \end{equation}

Since $f$ is an isometry of a connected metric nilpotent Lie group, then $f$ is affine, i.e., it is of the form $f = L_g \circ \widetilde{f}$ for some $g \in G$ and some isometry $\widetilde{f} \in \mathrm{Aut}(G)$; see \cite[Theorem 1.2]{MR3646026}.

 We claim that the abelianization map $\widetilde{f}_\mathrm{ab}$ of $\widetilde{f}$ is the identity map. Indeed, since the map $\pi_\mathrm{ab}$ is a submetry for the quotient metric $d_\mathrm{ab}$, we get
 \begin{eqnarray*}
 C &\stackrel{\eqref{bounded 1}}{\ge}& d(f(p),\varphi(p)) \ge d_\mathrm{ab}(\pi_\mathrm{ab} \circ f (p),\pi_\mathrm{ab} \circ \varphi (p)) \\ &=& d_\mathrm{ab}(L_{\pi_\mathrm{ab}(g)} \circ \widetilde{f}_\mathrm{ab}(\pi_\mathrm{ab} (p)), \pi_\mathrm{ab} (p) ), \quad \text{for every $p \in G$,}
 \end{eqnarray*}
 where we used that $\varphi_\mathrm{ab}=\mathrm{id}$. Therefore,
 \begin{equation*}
 d_\mathrm{ab}(\widetilde{f}_\mathrm{ab} \circ \pi_\mathrm{ab} (p), \pi_\mathrm{ab} (p)) \le C + d_\mathrm{ab}(e,\pi_\mathrm{ab}(g)), \quad \text{for every $p \in G$.}
 \end{equation*}
 The latter estimate implies that $\widetilde{f}_\mathrm{ab}$, which is a linear map on the abelian group $G_\mathrm{ab}$, is at bounded distance from the identity map. We conclude that $\widetilde{f}_\mathrm{ab}$ is the identity map. 
 Thanks to \cite[Lemma~2.5]{MR3646026}, the map $\widetilde{f}$, which is an isometry of $(G,d)$, is also an isometry of $(G,d_R)$, for some Riemannian metric $d_R$ on $G$. Since $\mathrm{d}_e \widetilde{f}$ is a Lie algebra automorphism of $\mathfrak{g}$, then $\mathrm{d}_e \widetilde{f}([\mathfrak{g},\mathfrak{g}])=[\mathfrak{g},\mathfrak{g}]$. Since $\mathrm{d}_e \widetilde{f}$ is an isometry for a Euclidean norm, we also get $\mathrm{d}_e \widetilde{f}([\mathfrak{g},\mathfrak{g}]^\perp)=[\mathfrak{g},\mathfrak{g}]^\perp$. Thanks to \cref{equality automorphism}, we infer that $\widetilde{f}$ is the identity map as well, thus $f = L_g$ for some $g \in G$.

 In particular, since right-translations are at bounded distance from the identity map, we obtain that $\varphi$ is at bounded distance from $C_g \in \mathrm{Aut}(G)$. Thanks to \cref{bounded auto}, we conclude that $\varphi =C_g$.

We point out that, in every simply connected, $2$-step nilpotent Lie group $G$, the map
\begin{equation} \label{vast class 2}
 \varphi \colon G \to G, \quad g \mapsto g \cdot L(\pi_\mathrm{ab}(g))
\end{equation}
is a Lie group automorphism of $G$, for every linear map $L \colon G_\mathrm{ab} \to [G,G]$. In particular, an automorphism $\varphi$ as in \eqref{vast class 2} satisfies $\varphi_\mathrm{ab}=\mathrm{id}$. We conclude that the class of Lie group automorphisms $\varphi$ satisfying the hypothesis of \cref{many quasi isometries} contains an abelian subgroup isomorphic to the vector space of linear maps from $G_\mathrm{ab}$ to $[G, G]$. 

A dimensional argument shows that, as soon as $\dim([G ,G])>1$ or $[G, G]$ is strictly contained in the center $Z(G)$ of $G$, then there are maps $\varphi \in \mathrm{Aut}(G)$ as in \eqref{vast class 2} that are not of the form $C_g$ for any $g \in G$. Combining \cref{many quasi isometries} with \cref{bounded iso}, we infer that those maps $\varphi$ are rough isometries that are not at bounded distance from any isometry.

\label{final example}
 We exhibit an explicit example of a Lie group automorphism of a sub-Riemannian Lie group that is a rough isometry, but it is not at bounded distance from any isometry. We consider $G = \mathbb H \times \mathbb R$ to be the simply connected $2$-step nilpotent Lie group whose associated Lie algebra $\mathfrak{g}$ admits a basis $\set{X,Y,Z,T}$ such that the only non-trivial bracket relation between elements of the basis is $[X,Y]=Z$.
 We consider on $G$ the sub-Riemannian structure $(\Delta,\rho)$ such that $\set{X,Y,T}$ is an orthonormal frame for $\rho$, and we denote by $d$ the corresponding sub-Riemannian metric. We identify $\mathbb H \times \mathbb R$ with $\mathbb R^4$ with the global diffeomorphism
 \begin{equation*}
 \Phi \colon \mathbb R^4 \to \mathbb H \times \mathbb R, \quad (x,y,z,t) \mapsto \exp(xX + yY + zZ + tT).
 \end{equation*}
Let $\varphi \in \mathrm{Aut}(G)$ be the Lie group automorphism such that, in coordinates,
 \begin{equation*} 
 \varphi(x,y,z,t)=(x,y,z+t,t).
 \end{equation*}
 On the one hand, we observe that $\varphi_\mathrm{ab}$ is the identity map and therefore, from \cref{many quasi isometries}, we get that $\varphi$ is a rough isometry. On the other hand $p = (0,0,0,1)$ is in the center of $G$, but $\varphi(p) \neq p$. We infer that $\varphi$ is not of the form $C_g$ for any $g \in G$. In view of \cref{bounded iso}, we conclude that $\varphi$ is not at bounded distance from an isometry.
